from datetime import date, timedelta
import calendar

def recur(start: str, rule: str, count: int) -> list[str]:
    start_date = date.fromisoformat(start)
    parts = rule.split()
    rule_type = parts[0]
    res = []

    if rule_type == "DAILY":
        K = int(parts[1])
        n = 0
        while len(res) < count:
            d = start_date + timedelta(days=n * K)
            if d >= start_date:
                res.append(d)
            n += 1

    elif rule_type == "WEEKLY":
        K = int(parts[1])
        days_str = parts[2].split(',')
        day_map = {'MO':0, 'TU':1, 'WE':2, 'TH':3, 'FR':4, 'SA':5, 'SU':6}
        target_days = [day_map[d.strip()] for d in days_str]

        monday_w0 = start_date - timedelta(days=start_date.weekday())

        n = 0
        while len(res) < count:
            week_start = monday_w0 + timedelta(weeks=n * K)
            for d_idx in target_days:
                d = week_start + timedelta(days=d_idx)
                if d >= start_date:
                    res.append(d)
            n += 1

    elif rule_type == "MONTHLY":
        K = int(parts[1])
        if len(parts) == 3:
            D_str = parts[2]
            is_last = (D_str == '-1')

            n = 0
            while len(res) < count:
                total_months = start_date.month - 1 + n * K
                year = start_date.year + total_months // 12
                month = total_months % 12 + 1

                if is_last:
                    day = calendar.monthrange(year, month)[1]
                else:
                    day = int(D_str)
                    if day > calendar.monthrange(year, month)[1]:
                        n += 1
                        continue

                d = date(year, month, day)
                if d >= start_date:
                    res.append(d)
                n += 1
        else:
            N = int(parts[2])
            WD_str = parts[3]
            day_map = {'MO':0, 'TU':1, 'WE':2, 'TH':3, 'FR':4, 'SA':5, 'SU':6}
            target_wd = day_map[WD_str.strip()]

            n = 0
            while len(res) < count:
                total_months = start_date.month - 1 + n * K
                year = start_date.year + total_months // 12
                month = total_months % 12 + 1

                days_in_month = calendar.monthrange(year, month)[1]
                matches = []
                for d in range(1, days_in_month + 1):
                    if date(year, month, d).weekday() == target_wd:
                        matches.append(d)

                if matches:
                    if N == -1:
                        day = matches[-1]
                    else:
                        if N <= len(matches):
                            day = matches[N-1]
                        else:
                            n += 1
                            continue

                    d = date(year, month, day)
                    if d >= start_date:
                        res.append(d)
                n += 1

    elif rule_type == "YEARLY":
        K = int(parts[1])
        mm, dd = map(int, parts[2].split('-'))

        n = 0
        while len(res) < count:
            year = start_date.year + n * K
            try:
                d = date(year, mm, dd)
                if d >= start_date:
                    res.append(d)
            except ValueError:
                pass
            n += 1

    res.sort()
    return [d.isoformat() for d in res[:count]]
